import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788343875000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file, and nothing is written to disk.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>FRESHRSS_URL</code></td><td>yes</td><td>Root URL of the instance, e.g. <code>https://rss.example.com</code>. The API path <code>/api/greader.php</code> is appended automatically.</td></tr><tr><td><code>FRESHRSS_USER</code></td><td>yes</td><td>FreshRSS user name.</td></tr><tr><td><code>FRESHRSS_API_PASSWORD</code></td><td>yes</td><td>The <strong>API password</strong> from Settings → Profile → API management, not the web login password.</td></tr><tr><td><code>FRESHRSS_READ_ONLY</code></td><td>no</td><td><code>1</code>, <code>true</code> or <code>yes</code> registers only the read tools.</td></tr><tr><td><code>FRESHRSS_INSECURE_TLS</code></td><td>no</td><td><code>true</code> accepts a self-signed certificate for this connection only.</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed.</strong></td></tr></tbody></table><p>See the <a href="/reference/environment">environment reference</a> for the exact validation rules.</p><h2 id="freshrss-url" tabindex="-1"><code>FRESHRSS_URL</code> <a class="header-anchor" href="#freshrss-url" aria-label="Permalink to “FRESHRSS_URL”">​</a></h2><p>Point it at the <strong>root</strong> of the instance — where the web interface lives — not at the API path. <code>https://rss.example.com</code> is right; <code>https://rss.example.com/api/greader.php</code> is not, and produces a 404 with a hint saying so.</p><p>The URL is validated at startup and the process exits on a bad value, because a malformed URL is exactly how credentials get sent to the wrong host:</p><ul><li>Only <code>http://</code> and <code>https://</code> are accepted.</li><li>Credentials embedded in the URL (<code>https://user:pass@host</code>) are rejected — use <code>FRESHRSS_USER</code> and <code>FRESHRSS_API_PASSWORD</code>.</li><li>Trailing slashes are stripped.</li><li>Plain <code>http://</code> to a non-loopback host is a warning, not an error: the API password would travel unencrypted.</li></ul><h2 id="freshrss-read-only" tabindex="-1"><code>FRESHRSS_READ_ONLY</code> <a class="header-anchor" href="#freshrss-read-only" aria-label="Permalink to “FRESHRSS_READ_ONLY”">​</a></h2><p>With <code>1</code>, <code>true</code> or <code>yes</code> — any casing, surrounding whitespace ignored — the write tools are <strong>not registered at all</strong>: they do not appear in <code>tools/list</code>. This is deliberate: a tool that exists but refuses at call time still invites the model to try, and still shows up in the client&#39;s tool picker.</p><p>It is read that tolerantly on purpose, and <code>FRESHRSS_INSECURE_TLS</code> below is not. This switch turns a protection <strong>on</strong>, so a value the operator meant as yes but spelled as <code>1</code> has to be taken as yes — being strict here means handing somebody who asked for the guard a server with every write tool, and no way to notice. The other switch turns a protection <strong>off</strong>, where being strict is what keeps a typo harmless.</p><p>Read-only leaves eight tools: <code>get_user_info</code>, <code>list_feeds</code>, <code>list_categories</code>, <code>get_unread_counts</code>, <code>list_articles</code>, <code>get_articles</code>, <code>list_article_ids</code> and <code>export_opml</code>.</p><h2 id="freshrss-insecure-tls" tabindex="-1"><code>FRESHRSS_INSECURE_TLS</code> <a class="header-anchor" href="#freshrss-insecure-tls" aria-label="Permalink to “FRESHRSS_INSECURE_TLS”">​</a></h2><p>For an instance with a self-signed certificate. It is implemented as a scoped <a href="https://undici.nodejs.org" target="_blank" rel="noreferrer">undici</a> dispatcher, <strong>not</strong> by setting <code>NODE_TLS_REJECT_UNAUTHORIZED</code> — so it relaxes validation for connections to your FreshRSS instance and nothing else in the process. The server announces it on stderr at startup so it cannot be on by accident and forgotten.</p><p>A proper certificate is still better. This exists so a homelab instance is usable today, not as a recommendation.</p><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to “Timeouts”">​</a></h2><p>Not configurable, but worth knowing:</p><ul><li><strong>30 s</strong> for normal requests.</li><li><strong>120 s</strong> for <code>subscribe_feed</code> and <code>import_opml</code>. Both make FreshRSS fetch from the internet before answering — <code>quickadd</code> downloads and parses the feed, and <code>subscription/import</code> subscribes to every entry in the OPML and then refreshes all of them.</li></ul><h2 id="credential-handling" tabindex="-1">Credential handling <a class="header-anchor" href="#credential-handling" aria-label="Permalink to “Credential handling”">​</a></h2><p><code>FRESHRSS_API_PASSWORD</code> is deleted from <code>process.env</code> immediately after the config is read, on every code path — including the ones that then exit. Otherwise it stays visible to child processes and in <code>/proc/&lt;pid&gt;/environ</code> for the process lifetime.</p><p>The login uses POST rather than GET so the password does not land in the FreshRSS access log, and both the auth token and the write token are cached in memory only.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you. <code>FRESHRSS_ALLOW_TOOLS</code> and <code>FRESHRSS_DENY_TOOLS</code> let you draw your own:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">FRESHRSS_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">FRESHRSS_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">list_feeds,list_articles,mark_articles</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">FRESHRSS_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_*</span></span></code></pre></div><p>Why bother, when all sixteen work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, sixteen is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_x</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of seven:</p><p><code>list_feeds</code>, <code>list_categories</code>, <code>get_unread_counts</code>, <code>list_articles</code>, <code>get_articles</code>, <code>mark_articles</code>, <code>mark_all_as_read</code>.</p><p>It composes — naming a tool alongside it puts that one back, and <code>FRESHRSS_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>FRESHRSS_ALLOW_TOOLS</code> decides what is in; <code>FRESHRSS_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>FRESHRSS_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, and <code>FRESHRSS_ALLOW_TOOLS=essential</code> narrows to the read half of the preset.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>FRESHRSS_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};